/**
 * Cross-language parity of the L1 integrity rules (review-v2-phase0, finding M1).
 *
 * `contracts/differential/integrity.corpus.json` is generated by
 * `backend/tests/integrity_corpus.py` from `app/graph_integrity.py`: random
 * contract-valid documents plus the exact [code, path, message] list Python
 * produces for each. validateGraph() must produce the identical list - same
 * rules, paths, order and English message (including Python-style repr() of
 * ids with quotes, control and astral characters).
 */
import { readFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'
import type { ArchGraph } from './types'
import { INTEGRITY_RULES, integrityErrors } from './validate'

interface Case { document: ArchGraph; expect: [string, string, string][] }

const corpusPath = resolve(dirname(fileURLToPath(import.meta.url)), '../../../contracts/differential/integrity.corpus.json')
const corpus = JSON.parse(readFileSync(corpusPath, 'utf-8')) as { cases: Case[] }

describe('integrity differential corpus (TypeScript vs Python)', () => {
  it('covers every INT rule', () => {
    const seen = new Set(corpus.cases.flatMap((c) => c.expect.map(([code]) => code)))
    expect([...seen].sort()).toEqual([...INTEGRITY_RULES].sort())
  })

  it.each(corpus.cases.map((c, index) => [index, c] as const))('case %i: same codes, paths, order and messages', (_index, c) => {
    const got = integrityErrors(c.document).map((problem) => [problem.ruleId, problem.path, problem.message.en])
    expect(got).toEqual(c.expect)
  })
})
